/** Immutable Visual Memory v1 rules. Private seeds are generated by the server. */
export function visualMemoryRules(level: number) {
  if (!Number.isInteger(level) || level < 1 || level > 1_000_000)
    throw new Error('Invalid Visual Memory level');
  const gridSize =
    level < 3 ? 3 : level < 6 ? 4 : level < 10 ? 5 : level < 15 ? 6 : level < 21 ? 7 : 8;
  return {
    gridSize,
    targetCount: Math.min(level + 2, 48),
    displayMs: Math.max(600, 1500 - Math.max(0, level - 46) * 25),
  };
}

export function visualMemoryPattern(seed: string, level: number, attempt: number): number[] {
  if (!Number.isInteger(attempt) || attempt < 1 || attempt > 3) throw new Error('Invalid attempt');
  const { gridSize, targetCount } = visualMemoryRules(level);
  let value = 2166136261;
  for (const char of `visual-memory:v1:${seed}:${level}:${attempt}`)
    value = Math.imul(value ^ char.charCodeAt(0), 16777619);
  const tiles = Array.from({ length: gridSize * gridSize }, (_, i) => i);
  for (let i = tiles.length - 1; i > 0; i--) {
    value += 0x6d2b79f5;
    let n = Math.imul(value ^ (value >>> 15), 1 | value);
    n ^= n + Math.imul(n ^ (n >>> 7), 61 | n);
    const j = Math.floor((((n ^ (n >>> 14)) >>> 0) / 4294967296) * (i + 1));
    [tiles[i], tiles[j]] = [tiles[j], tiles[i]];
  }
  let pattern = tiles.slice(0, targetCount).sort((a, b) => a - b);
  if (
    attempt > 1 &&
    JSON.stringify(pattern) === JSON.stringify(visualMemoryPattern(seed, level, attempt - 1))
  ) {
    // A retry must visibly change the pattern, even when two random samples coincide.
    pattern = pattern.map((tile) => (tile + 1) % (gridSize * gridSize)).sort((a, b) => a - b);
  }
  return pattern;
}

// Completing a level always outweighs partial recall. No client clocks or speed bonuses.
export function visualMemoryScore(level: number, correct: number, totalMistakes: number) {
  return Math.max(0, (level - 1) * 1000 + correct * 10 - totalMistakes);
}
